#include "Monstey_NavSeamGround.hpp"
#include "Monstey_Core.hpp"
#include <cstring>
#include <iostream>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using M=Monstey_NavigationBoundaryMeshView;using J=Monstey_Json;
struct OwnedMesh{Monstey_Bytes faces=Monstey_Bytes(16),edges=Monstey_Bytes(80),vertices=Monstey_Bytes(64);std::array<std::int32_t,1>fm{-1};std::array<std::int32_t,4>em{-1,-1,-1,-1};M View()const{M m{};m.faces=faces;m.edges=edges;m.vertices=vertices;m.face_map=fm;m.edge_map=em;m.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return m;}};
OwnedMesh Quad(const std::array<V,4>&p){OwnedMesh m;Monstey_PutU32(m.faces,0,0);Monstey_PutU16(m.faces,8,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(m.edges,i*20,i);Monstey_PutU32(m.edges,i*20+4,(i+1)%4);Monstey_PutU32(m.edges,i*20+8,0xffffffff);Monstey_PutU32(m.edges,i*20+12,0xffffffff);std::memcpy(m.vertices.data()+i*16,p[i].data(),16);}return m;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0;auto a=Quad({V{0,0,0,13},V{2,0,0,17},V{2,0,-2,19},V{0,0,-2,23}});auto b=Quad({V{2,0,0,31},V{0,0,0,37},V{0,0,2,41},V{2,0,2,43}});const V up{0,1,0,0};Monstey_NavSeamGroundSettings s{.5f,.1f,.01f,.0001f,.9f,.9f,.02f};auto Run=[&](const M&av,const M&bv,const auto&settings,int expected){const auto got=Monstey_NavSeamGroundMatch(av,bv,0,0,0,0,up,settings);Monstey_Require(got.status==expected,std::string("Ground edge-pair status differs at group ")+std::to_string(groups)+": expected "+std::to_string(expected)+", got "+std::to_string(got.status));++groups;return got;};const auto av=a.View(),bv=b.View();const auto valid=Run(av,bv,s,-1);Monstey_Require(valid.candidate.edge_a==0&&valid.candidate.edge_b==0&&valid.candidate.face_a==0&&valid.candidate.face_b==0&&valid.candidate.enabled,"Candidate identities lost");Monstey_Require(valid.candidate.intervals==std::array<float,4>{0,1,0,1}&&valid.candidate.score<1e-10f,"Coincident full interval or score differs");auto moved=bv;moved.transform[3]=V{0,1,0,0};Run(av,moved,s,6);moved=bv;moved.transform[3]=V{0,0,-.2f,0};Run(av,moved,s,2);moved=bv;moved.transform[3]=V{3,0,0,0};Run(av,moved,s,3);moved=bv;moved.transform[3]=V{1,0,0,0};auto shortOverlap=s;shortOverlap.minimum_overlap=1.5f;Run(av,moved,shortOverlap,4);auto same=Quad({V{0,0,0,0},V{2,0,0,0},V{2,0,-2,0},V{0,0,-2,0}});Run(av,same.View(),s,0);auto tilted=Quad({V{2,0,0,0},V{0,4,0,0},V{0,4,-2,0},V{2,0,-2,0}});Run(av,tilted.View(),s,1);auto noSupport=b;Monstey_PutU16(noSupport.faces,8,1);Run(av,noSupport.View(),s,8);auto noMinimum=s;noMinimum.face_support=0;Run(av,noSupport.View(),noMinimum,-1);for(unsigned i=1;i<=32;++i){const float scale=static_cast<float>(i)*.25f;auto scaledA=av,scaledB=bv;scaledA.transform[0][0]=scale;scaledB.transform[0][0]=scale;const auto got=Run(scaledA,scaledB,s,-1);Monstey_Require(got.candidate.intervals==valid.candidate.intervals,"Shared affine scale changed full-edge intervals");}auto translatedA=av,translatedB=bv;translatedA.transform[3]=V{13,-7,21,100};translatedB.transform[3]=translatedA.transform[3];Run(translatedA,translatedB,s,-1);bool bad=false;try{(void)Monstey_NavSeamGroundMatch(av,bv,0,100,0,0,up,s);}catch(const std::exception&){bad=true;}Monstey_Require(bad,"Invalid owned edge accepted");++groups;Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"native_status_cases",J::array({-1,0,1,2,3,4,6,8})},{"uncovered_status_cases",J::array({5,7,9})},{"native_program_called",false},{"scope","NULL-callback ground edge-pair candidate; not complete557F20 matcher or native-execution proof"}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" ground edge-pair groups\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}